"""Locate or download the Kaggle Give Me Some Credit cs-training.csv (R1).

Resolution order:
1. an already-valid workspace copy (data/raw/cs-training.csv),
2. any copy/zip inside the shared REPRO_DATA_CACHE folder,
3. the Kaggle API via kagglehub (only if credentials exist),
4. the Hugging Face mirror of the competition zip (no login required).

The extracted CSV is cached under REPRO_DATA_CACHE so later runs are offline.
"""
from __future__ import annotations

import os
import shutil
import zipfile
from pathlib import Path

import pandas as pd
import requests

from config import ID_COLS, PREDICTORS, RAW_CSV, RAW_DIR, TARGET_COL

CACHE_DIR = Path(os.environ.get("REPRO_DATA_CACHE", RAW_DIR))
CACHE_SUBDIR = CACHE_DIR / "gmsc"
ZIP_NAME = "Give-Me-Some-Credit.zip"
HF_URL = (
    "https://huggingface.co/datasets/algcache/GiveMeSomeCredit/resolve/main/"
    + ZIP_NAME
)
KAGGLE_DATASET = "kgshatg8mever/give-me-some-credit"  # kagglehub mirror id

EXPECTED_COLS = [TARGET_COL] + PREDICTORS
MIN_ROWS = 150_000  # the released cs-training.csv has exactly 150,000 rows


def _valid(path: Path) -> bool:
    try:
        df = pd.read_csv(path)
    except Exception:
        return False
    return (
        len(df) == MIN_ROWS
        and TARGET_COL in df.columns
        and all(c in df.columns for c in PREDICTORS)
        and set(ID_COLS).issubset(df.columns)
    )


def _use_or_copy(src: Path) -> Path:
    RAW_DIR.mkdir(parents=True, exist_ok=True)
    if src.resolve() != RAW_CSV.resolve():
        shutil.copyfile(src, RAW_CSV)
    print(f"[data] using cs-training.csv: {RAW_CSV}")
    return RAW_CSV


def _from_cache() -> Path | None:
    if not CACHE_DIR.is_dir():
        return None
    for candidate in CACHE_SUBDIR.glob("cs-training.csv"):
        if _valid(candidate):
            return _use_or_copy(candidate)
    for zip_path in list(CACHE_DIR.glob(ZIP_NAME)) + list(CACHE_SUBDIR.glob(ZIP_NAME)):
        if _extract_zip(zip_path):
            return _use_or_copy(CACHE_SUBDIR / "cs-training.csv")
    # any other cs-training.csv lying in the shared cache
    for candidate in CACHE_DIR.rglob("cs-training.csv"):
        if _valid(candidate):
            CACHE_SUBDIR.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(candidate, CACHE_SUBDIR / "cs-training.csv")
            return _use_or_copy(CACHE_SUBDIR / "cs-training.csv")
    return None


def _extract_zip(zip_path: Path) -> bool:
    try:
        CACHE_SUBDIR.mkdir(parents=True, exist_ok=True)
        with zipfile.ZipFile(zip_path) as zf:
            zf.extractall(CACHE_SUBDIR)
        return _valid(CACHE_SUBDIR / "cs-training.csv")
    except Exception as exc:  # pragma: no cover - defensive
        print(f"[data] could not extract {zip_path}: {exc}")
        return False


def _kaggle_download() -> Path | None:
    """Try the official Kaggle files; requires accepted rules + credentials."""
    try:
        import kagglehub  # type: ignore
    except ImportError:
        return None
    has_creds = bool(
        os.environ.get("KAGGLE_USERNAME")
        and os.environ.get("KAGGLE_KEY")
    ) or Path.home().joinpath(".kaggle", "kaggle.json").exists()
    if not has_creds:
        return None
    try:
        folder = Path(kagglehub.dataset_download(KAGGLE_DATASET))
        for candidate in folder.rglob("cs-training.csv"):
            if _valid(candidate):
                CACHE_SUBDIR.mkdir(parents=True, exist_ok=True)
                shutil.copyfile(candidate, CACHE_SUBDIR / "cs-training.csv")
                return _use_or_copy(CACHE_SUBDIR / "cs-training.csv")
    except Exception as exc:  # pragma: no cover - depends on credentials
        print(f"[data] Kaggle download failed ({exc}); falling back.")
    return None


def _hf_download() -> Path | None:
    CACHE_DIR.mkdir(parents=True, exist_ok=True)
    zip_path = CACHE_DIR / ZIP_NAME
    if not zip_path.exists():
        print(f"[data] downloading GMSC zip from Hugging Face mirror ...")
        with requests.get(HF_URL, timeout=600, stream=True) as resp:
            resp.raise_for_status()
            tmp = zip_path.with_suffix(".part")
            with open(tmp, "wb") as fh:
                for chunk in resp.iter_content(chunk_size=1 << 20):
                    fh.write(chunk)
            tmp.replace(zip_path)
        print(f"[data] cached {zip_path} ({zip_path.stat().st_size} bytes)")
    if _extract_zip(zip_path):
        return _use_or_copy(CACHE_SUBDIR / "cs-training.csv")
    return None


def ensure_raw_csv() -> Path:
    for provider in (_from_cache, _kaggle_download, _hf_download):
        path = provider()
        if path is not None:
            return path
    raise RuntimeError(
        "cs-training.csv could not be obtained. The Kaggle competition file "
        "requires accepting the competition rules; place it manually at "
        f"{RAW_CSV} and re-run."
    )


if __name__ == "__main__":
    path = ensure_raw_csv()
    df = pd.read_csv(path)
    print(f"[data] rows={len(df)} cols={list(df.columns)}")
    print(f"[data] missing MonthlyIncome={df['MonthlyIncome'].isna().sum()}, "
          f"NumberOfDependents={df['NumberOfDependents'].isna().sum()}")
    print(f"[data] default rate={df[TARGET_COL].mean():.4f}")

